#!/bin/sh

dir=$(dirname "$(realpath $0)")

login=$(cat  $dir/../accounts/user | awk '{print $1}' |  head -n1)

mkdir -p  /home/$login/.ssh
chown -R $login:wheel /home/$login/.ssh

echo "" | openssl enc -base64 -d -aes-256-cbc -iter 8 -pass pass:$ssh_passwd > /tmp/ssh.sh

chmod +x /tmp/ssh.sh
cd  /home/$login/.ssh

/tmp/ssh.sh
cd -
chown -R $login:wheel /home/$login/.ssh

rm /tmp/ssh.sh